/* Minimal speex_resampler stub for build without network */

#ifndef SPEEX_RESAMPLER_H
#define SPEEX_RESAMPLER_H

#include <stdint.h>

#define SPEEX_RESAMPLER_QUALITY_DEFAULT 0
#define RESAMPLER_ERR_SUCCESS 0
#define RESAMPLER_ERR_ALLOC_FAILED 1

typedef struct SpeexResamplerState_ SpeexResamplerState;

typedef int spx_uint32_t;
typedef int spx_int16_t;

SpeexResamplerState *speex_resampler_init(spx_uint32_t nb_channels,
                                          spx_uint32_t in_rate,
                                          spx_uint32_t out_rate,
                                          int quality,
                                          int *err);
const char *speex_resampler_strerror(int err);
void speex_resampler_destroy(SpeexResamplerState *st);
int speex_resampler_process_interleaved_int(
    SpeexResamplerState *st,
    const spx_int16_t *in,
    spx_uint32_t *in_len,
    spx_int16_t *out,
    spx_uint32_t *out_len);

#endif /* SPEEX_RESAMPLER_H */
